:host,ha-card,.shell,.runtime,.runtime-content{display:block;width:100%!important;height:100%!important;min-width:0!important;min-height:0!important;box-sizing:border-box!important;padding:0!important;background:transparent!important;box-shadow:none!important;overflow:visible!important}
.hk-card,.hk-card *{box-sizing:border-box}
