.hk-kicker{display:block;color:var(--hk-muted);font-size:9px;font-weight:760;letter-spacing:.13em;text-transform:uppercase}.hk-name{display:block;overflow:hidden;font-size:clamp(17px,8cqh,23px);font-weight:700;letter-spacing:-.04em;text-overflow:ellipsis;white-space:nowrap}.hk-state{display:block;overflow:hidden;color:var(--hk-muted);font-size:11px;font-weight:540;text-overflow:ellipsis;white-space:nowrap}
