] .hkr-summary{align-content:center;padding:0}.hk-room[data-layout="compact"] .hkr-summary>strong{font-size:24px}.hk-room[data-layout="compact"] .hkr-summary>button{display:none}.hk-room[data-layout="compact"] .hkr-categories{grid-template-columns:repeat(4,1fr);border-left:0}.hk-room[data-layout="compact"] .hkr-categories button{grid-template-columns:1fr;justify-items:center;padding:5px 2px;text-align:center}.hk-room[data-layout="compact"] .hkr-categories ha-icon,.hk-room[data-layout="compact"] .hkr-categories small{display:none}.hk-room[data-layout="compact"]>header small{display:none}.hk-room[data-layout="micro"]{padding:9px 11px}.hk-room[data-layout="micro"]>header{display:none}.hk-room[data-layout="micro"]>main{height:100%;grid-template-columns:1fr 145px;gap:8px}.hk-room[data-layout="micro"] .hkr-summary{align-content:center}.hk-room[data-layout="micro"] .hkr-summary>strong{font-size:20px}.hk-room[data-layout="micro"] .hkr-summary>span,.hk-room[data-layout="micro"] .hkr-summary>button,.hk-room[data-layout="micro"] .hk-settings{display:none}.hk-room[data-layout="micro"] .hkr-categories button{grid-template-columns:1fr;justify-items:center;padding:3px}.hk-room[data-layout="micro"] .hkr-categories ha-icon,.hk-room[data-layout="micro"] .hkr-categories small{display:none}.hk-room[data-layout="micro"] .hkr-categories strong{font-size:9px}
.hk-room[data-layout="wide"] .hkr-categories button{grid-template-columns:18px minmax(0,1fr);gap:5px;padding-inline:6px}.hk-room[data-layout="wide"] .hkr-categories ha-icon{--mdc-icon-size:17px}

